-- Ascend · question batch. Original questions, correct answers spread evenly across A–D.
-- Run in the Supabase SQL editor. Safe to re-run (existing ids are skipped).
insert into public.ascend_questions (id, subject, level, domain, skill, passage, data_table, question, choices, answer_index, accept, explanation, status, source, published_at) values
('mathl3c_001', 'math', 3, 'Algebra', 'Linear equations in one variable', null, null, 'If 7 − (2x − 3)/4 = 2x, what is the value of x?', null, null, '["3.1", "31/10"]'::jsonb, 'Multiply by 4: 28 − (2x − 3) = 8x, so 31 − 2x = 8x, 10x = 31 and x = 3.1.', 'published', 'import', now()),
('mathl3c_002', 'math', 3, 'Algebra', 'Linear equations in one variable', null, null, 'In the equation p(2x − 1) = 6x + q, p and q are constants. The equation has no solution. Which of the following must be true?', '["p = 3 and q ≠ −3", "q = 0", "p = 3 and q = −3", "p ≠ 3"]'::jsonb, 0, null, 'Expanding: 2px − p = 6x + q. The x terms cancel when 2p = 6, so p = 3; then −3 = q would make every x work, so for no solution q ≠ −3.', 'published', 'import', now()),
('mathl3c_003', 'math', 3, 'Algebra', 'Linear equations in one variable', null, null, 'If 3/(x + 2) = 5/(2x − 1), and x ≠ −2 and x ≠ 1/2, what is the value of x?', '["13", "11", "−13", "7"]'::jsonb, 0, null, 'Cross-multiply: 3(2x − 1) = 5(x + 2), so 6x − 3 = 5x + 10 and x = 13.', 'published', 'import', now()),
('mathl3c_004', 'math', 3, 'Algebra', 'Linear functions', null, null, 'A linear function g satisfies g(3) − g(1) = 10 and g(0) = −4. What is g(5)?', '["46", "6", "21", "11"]'::jsonb, 2, null, 'The slope is 10 ÷ 2 = 5, so g(x) = 5x − 4 and g(5) = 21.', 'published', 'import', now()),
('mathl3c_005', 'math', 3, 'Algebra', 'Linear functions', null, null, 'A rental company charges a flat fee plus a per-mile rate. A 120-mile trip costs $86 and a 200-mile trip costs $118. What is the cost, in dollars, of a 300-mile trip?', null, null, '["158"]'::jsonb, 'The rate is (118 − 86) ÷ 80 = 0.40 per mile. Flat fee = 86 − 0.40(120) = 38. Cost = 38 + 0.40(300) = 158.', 'published', 'import', now()),
('mathl3c_006', 'math', 3, 'Algebra', 'Linear functions', null, null, 'The line y = ax + 3 is parallel to the line through (2, 5) and (6, −3). What is the x-intercept of y = ax + 3?', '["(3, 0)", "(1.5, 0)", "(−1.5, 0)", "(0, 3)"]'::jsonb, 1, null, 'The slope through the points is −8/4 = −2, so y = −2x + 3. Setting y = 0 gives x = 1.5.', 'published', 'import', now()),
('mathl3c_007', 'math', 3, 'Algebra', 'Systems of linear equations', null, null, '4x − 6y = 10
−6x + ky = −15

In the system, k is a constant. For which value of k does the system have infinitely many solutions?', '["−9", "4", "6", "9"]'::jsonb, 3, null, 'Multiply the first equation by −1.5: −6x + 9y = −15. The equations match when k = 9.', 'published', 'import', now()),
('mathl3c_008', 'math', 3, 'Algebra', 'Systems of linear equations', null, null, 'A boat travels 36 miles downstream in 2 hours and the same distance upstream in 3 hours. What is the speed of the current, in miles per hour?', '["3", "2", "6", "15"]'::jsonb, 0, null, 'Downstream speed is 18 and upstream speed is 12. Boat + current = 18 and boat − current = 12, so the current is 3.', 'published', 'import', now()),
('mathl3c_009', 'math', 3, 'Algebra', 'Systems of linear equations', null, null, 'x/2 + y/3 = 4
x/4 − y/6 = 0

What is the value of x + y?', null, null, '["10"]'::jsonb, 'Multiply: 3x + 2y = 24 and 3x − 2y = 0. Adding: 6x = 24, so x = 4, y = 6, and x + y = 10.', 'published', 'import', now()),
('mathl3c_010', 'math', 3, 'Algebra', 'Systems of linear equations', null, null, 'Concert tickets cost $25 for students and $40 for adults. A school spent $1,330 on 40 tickets. How many more adult tickets than student tickets were bought?', '["22", "2", "6", "4"]'::jsonb, 3, null, 's + a = 40 and 25s + 40a = 1,330. Substituting s = 40 − a: 1,000 + 15a = 1,330, so a = 22 and s = 18. That is 4 more adult tickets.', 'published', 'import', now()),
('mathl3c_011', 'math', 3, 'Algebra', 'Linear inequalities', null, null, 'A phone company offers Plan A: $40 per month plus $0.10 per minute, and Plan B: $25 per month plus $0.25 per minute. For what numbers of minutes m is Plan A cheaper?', '["m < 100", "m > 150", "m < 65", "m > 100"]'::jsonb, 3, null, 'Plan A is cheaper when 40 + 0.10m < 25 + 0.25m, so 15 < 0.15m and m > 100.', 'published', 'import', now()),
('mathl3c_012', 'math', 3, 'Algebra', 'Linear inequalities', null, null, 'Which ordered pair (x, y) satisfies y ≥ 3x − 2, y < −x + 6, and x > 0?', '["(3, 2)", "(−1, 0)", "(2, 5)", "(1, 3)"]'::jsonb, 3, null, '(1, 3): 3 ≥ 1 ✓, 3 < 5 ✓, 1 > 0 ✓. Each other pair fails at least one condition.', 'published', 'import', now()),
('mathl3c_013', 'math', 3, 'Advanced Math', 'Equivalent expressions', null, null, 'Which expression is equivalent to (x^{3} − 8)/(x − 2) for x ≠ 2?', '["x^{2} − 2x + 4", "x^{2} + 2x + 4", "x^{2} + 2x − 4", "x^{2} + 4"]'::jsonb, 1, null, 'x^{3} − 8 is a difference of cubes: (x − 2)(x^{2} + 2x + 4).', 'published', 'import', now()),
('mathl3c_014', 'math', 3, 'Advanced Math', 'Equivalent expressions', null, null, 'If (x + a)(x − 5) = x^{2} + bx − 15 for all x, what is the value of b?', '["2", "3", "−8", "−2"]'::jsonb, 3, null, '−5a = −15 gives a = 3. Then b = a − 5 = −2.', 'published', 'import', now()),
('mathl3c_015', 'math', 3, 'Advanced Math', 'Equivalent expressions', null, null, 'Which expression is equivalent to √(x^{6}y^{4}) for x > 0 and y > 0?', '["x^{2}y^{3}", "x^{4}y^{2}", "x^{3}y^{2}", "x^{3}y^{4}"]'::jsonb, 2, null, 'Halve each exponent: x^{3}y^{2}.', 'published', 'import', now()),
('mathl3c_016', 'math', 3, 'Advanced Math', 'Equivalent expressions', null, null, 'The expression 4x^{2} − 12x + 9 can be written as (ax + b)^{2}, where a > 0. What is a + b?', null, null, '["-1", "−1"]'::jsonb, '4x^{2} − 12x + 9 = (2x − 3)^{2}, so a = 2, b = −3, and a + b = −1.', 'published', 'import', now()),
('mathl3c_017', 'math', 3, 'Advanced Math', 'Nonlinear equations', null, null, 'What is the sum of all solutions to (x − 3)^{2} = 4x?', '["9", "10", "6", "4"]'::jsonb, 1, null, 'Expand: x^{2} − 6x + 9 = 4x, so x^{2} − 10x + 9 = 0. The solutions 1 and 9 sum to 10.', 'published', 'import', now()),
('mathl3c_018', 'math', 3, 'Advanced Math', 'Nonlinear equations', null, null, 'If 2^{x + 3} − 2^{x} = 56, what is the value of x?', '["4", "2", "3", "5"]'::jsonb, 2, null, '2^{x}(8 − 1) = 56, so 2^{x} = 8 and x = 3.', 'published', 'import', now()),
('mathl3c_019', 'math', 3, 'Advanced Math', 'Nonlinear equations', null, null, 'How many real solutions does x^{4} − 5x^{2} + 4 = 0 have?', '["0", "2", "3", "4"]'::jsonb, 3, null, 'Factor as (x^{2} − 1)(x^{2} − 4) = 0, giving x = ±1 and x = ±2.', 'published', 'import', now()),
('mathl3c_020', 'math', 3, 'Advanced Math', 'Nonlinear equations', null, null, 'In the xy-plane, the line y = 3 intersects the parabola y = x^{2} − 2x at two points. What is the distance between them?', null, null, '["4"]'::jsonb, 'x^{2} − 2x = 3 gives (x − 3)(x + 1) = 0, so x = 3 and x = −1. The distance is 4.', 'published', 'import', now()),
('mathl3c_021', 'math', 3, 'Advanced Math', 'Nonlinear functions', null, null, 'The function f(x) = x^{2} + bx + c has zeros at x = −1 and x = 5. What is the minimum value of f?', '["−9", "9", "−4", "−5"]'::jsonb, 0, null, 'f(x) = (x + 1)(x − 5). The vertex is at x = 2: f(2) = 3(−3) = −9.', 'published', 'import', now()),
('mathl3c_022', 'math', 3, 'Advanced Math', 'Nonlinear functions', null, null, 'A car''s value decreases by 15% each year. It was worth $24,000 when new. To the nearest dollar, what is it worth after 3 years?', '["14,739", "13,200", "17,340", "15,606"]'::jsonb, 0, null, '24,000 × 0.85^{3} = 24,000 × 0.614125 = 14,739.', 'published', 'import', now()),
('mathl3c_023', 'math', 3, 'Advanced Math', 'Nonlinear functions', null, null, 'The function p is defined by p(t) = 3 · 2^{t}. For what value of t does p(t) = 96?', null, null, '["5"]'::jsonb, '2^{t} = 32, so t = 5.', 'published', 'import', now()),
('mathl3c_024', 'math', 3, 'Advanced Math', 'Nonlinear functions', null, null, 'If f(x) = (x − 2)/(x + 3), for what value of x is f(x) = 2?', '["8", "−8", "4", "−4"]'::jsonb, 1, null, 'x − 2 = 2(x + 3), so x − 2 = 2x + 6 and x = −8.', 'published', 'import', now()),
('mathl3c_025', 'math', 3, 'Advanced Math', 'Nonlinear functions', null, null, 'The graph of y = −2(x + 1)^{2} + 8 crosses the x-axis at which x-values?', '["x = −1 and x = 8", "x = −3 and x = 1", "x = 3 and x = −1", "x = −3 and x = 3"]'::jsonb, 1, null, 'Set y = 0: (x + 1)^{2} = 4, so x + 1 = ±2 and x = 1 or −3.', 'published', 'import', now()),
('mathl3c_026', 'math', 3, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'Working alone, Ana can paint a room in 6 hours and Ben can paint it in 4 hours. Ana works alone for 1 hour, then Ben joins her. How many more hours does it take them to finish?', '["2.4", "2", "3", "1.6"]'::jsonb, 1, null, 'Ana paints 1/6 in the first hour, leaving 5/6. Together they paint 1/6 + 1/4 = 5/12 per hour, so they need (5/6) ÷ (5/12) = 2 hours.', 'published', 'import', now()),
('mathl3c_027', 'math', 3, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'A solution is 12% acid. How many milliliters of pure water must be added to 300 mL of the solution to make it 9% acid?', null, null, '["100"]'::jsonb, 'The acid stays at 0.12 × 300 = 36 mL. 36 ÷ 0.09 = 400 mL total, so add 100 mL of water.', 'published', 'import', now()),
('mathl3c_028', 'math', 3, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'A car''s speed is 66 feet per second. What is this speed in miles per hour? (1 mile = 5,280 feet)', '["30", "60", "45", "90"]'::jsonb, 2, null, '66 × 3,600 ÷ 5,280 = 45.', 'published', 'import', now()),
('mathl3c_029', 'math', 3, 'Problem-Solving and Data Analysis', 'Percentages', null, null, 'After a 25% discount and then an 8% sales tax, a jacket costs $81. What was the original price, in dollars?', '["92", "108", "75", "100"]'::jsonb, 3, null, '0.75 × 1.08 × P = 81, so 0.81P = 81 and P = 100.', 'published', 'import', now()),
('mathl3c_030', 'math', 3, 'Problem-Solving and Data Analysis', 'Percentages', null, null, 'Quantity A is 150% of quantity B, and B is 40% of C. A is what percent of C?', null, null, '["60", "60%"]'::jsonb, 'A = 1.5 × 0.4 × C = 0.6C, or 60% of C.', 'published', 'import', now()),
('mathl3c_031', 'math', 3, 'Problem-Solving and Data Analysis', 'Percentages', null, null, 'A city''s population fell by 10% one year and rose by 10% the next. What was the overall percent change?', '["A 10% decrease", "No change", "A 1% decrease", "A 1% increase"]'::jsonb, 2, null, '0.9 × 1.1 = 0.99, a 1% decrease.', 'published', 'import', now()),
('mathl3c_032', 'math', 3, 'Problem-Solving and Data Analysis', 'One-variable data', null, '{"h": ["Pets", "Students"], "r": [["0", "4"], ["1", "6"], ["2", "6"], ["3", "2"], ["4", "2"]]}'::jsonb, 'The table shows the number of pets owned by students in a class. What is the mean number of pets per student?', '["2.4", "1.6", "2", "1.5"]'::jsonb, 1, null, 'Total pets: 0(4) + 1(6) + 2(6) + 3(2) + 4(2) = 32, and there are 20 students. 32 ÷ 20 = 1.6.', 'published', 'import', now()),
('mathl3c_033', 'math', 3, 'Problem-Solving and Data Analysis', 'One-variable data', null, null, 'Data set P has 11 values with mean 20. Data set Q is formed by adding the value 31 to P. Which statement is true?', '["The mean of Q is 20 + 11/12", "The mean of Q is 25.5", "The mean of Q is 20", "The median of Q must be 31"]'::jsonb, 0, null, 'The total becomes 220 + 31 = 251, and 251 ÷ 12 = 20 + 11/12.', 'published', 'import', now()),
('mathl3c_034', 'math', 3, 'Problem-Solving and Data Analysis', 'One-variable data', null, null, 'Two data sets each have 6 values. Set M: 5, 10, 15, 20, 25, 30. Set N: 15, 16, 17, 18, 19, 20. Which statement is true?', '["Set M has a greater mean", "The sets have the same mean, and set M has a greater standard deviation", "Set N has a greater standard deviation", "The sets have the same standard deviation"]'::jsonb, 1, null, 'Both means are 17.5. Set M''s values are much more spread out, so its standard deviation is greater.', 'published', 'import', now()),
('mathl3c_035', 'math', 3, 'Problem-Solving and Data Analysis', 'Two-variable data', null, null, 'The equation y = 2,400 − 150x models the amount of money y, in dollars, left in a fund x months after it opened. How many months after opening will the fund have $600 left?', '["12", "16", "20", "4"]'::jsonb, 0, null, '2,400 − 150x = 600 gives 150x = 1,800 and x = 12.', 'published', 'import', now()),
('mathl3c_036', 'math', 3, 'Problem-Solving and Data Analysis', 'Two-variable data', null, null, 'A data set is best modeled by y = 40(1.5)^{x}. By what factor does y change when x increases by 2?', '["4.5", "2.25", "1.5", "3"]'::jsonb, 1, null, 'Increasing x by 2 multiplies y by 1.5^{2} = 2.25.', 'published', 'import', now()),
('mathl3c_037', 'math', 3, 'Problem-Solving and Data Analysis', 'Probability and conditional probability', null, null, 'A box has 4 red, 5 blue, and 6 green marbles. Two marbles are drawn without replacement. What is the probability that both are green?', '["4/25", "2/5", "6/35", "1/7"]'::jsonb, 3, null, '(6/15) × (5/14) = 30/210 = 1/7.', 'published', 'import', now()),
('mathl3c_038', 'math', 3, 'Problem-Solving and Data Analysis', 'Probability and conditional probability', null, null, 'In a group of 80 students, 50 take Spanish, 30 take French, and 12 take both. If a student who takes French is chosen at random, what is the probability the student also takes Spanish?', '["12/50", "2/5", "6/25", "3/20"]'::jsonb, 1, null, '12 of the 30 French students also take Spanish: 12/30 = 2/5.', 'published', 'import', now()),
('mathl3c_039', 'math', 3, 'Problem-Solving and Data Analysis', 'Inference from sample statistics', null, null, 'A researcher finds that, in a random sample of cities, those with more parks have lower average stress scores. Which conclusion is best supported?', '["Building parks will lower stress in any city", "Stress causes cities to build parks", "Cities with more parks tend to have lower stress scores, but the study does not show that parks cause lower stress", "Parks cause stress to increase"]'::jsonb, 2, null, 'An observational study shows an association, not cause and effect.', 'published', 'import', now()),
('mathl3c_040', 'math', 3, 'Problem-Solving and Data Analysis', 'Inference from sample statistics', null, null, 'A poll estimates that 54% of voters support a measure, with a margin of error of 4 percentage points. Which statement is most appropriate?', '["Support is at least 58%", "Exactly 54% of voters support the measure", "It is plausible that support is anywhere from 50% to 58%", "The measure will certainly pass"]'::jsonb, 2, null, 'The margin of error gives a plausible range of 54% ± 4%, from 50% to 58%.', 'published', 'import', now()),
('mathl3c_041', 'math', 3, 'Geometry and Trigonometry', 'Circles', null, null, 'A circle in the xy-plane has center (3, −2) and is tangent to the x-axis. Which equation represents the circle?', '["(x − 3)^{2} + (y + 2)^{2} = 4", "(x − 3)^{2} + (y + 2)^{2} = 2", "(x + 3)^{2} + (y − 2)^{2} = 4", "(x − 3)^{2} + (y + 2)^{2} = 9"]'::jsonb, 0, null, 'Tangent to the x-axis means the radius equals the distance from the center to the axis: |−2| = 2, so r^{2} = 4.', 'published', 'import', now()),
('mathl3c_042', 'math', 3, 'Geometry and Trigonometry', 'Circles', null, null, 'In a circle, a central angle of 2.5 radians intercepts an arc of length 20. What is the radius?', null, null, '["8"]'::jsonb, 'Arc length = rθ, so 20 = 2.5r and r = 8.', 'published', 'import', now()),
('mathl3c_043', 'math', 3, 'Geometry and Trigonometry', 'Circles', null, null, 'Points A and B lie on a circle with center O and radius 9. Angle AOB measures 80°. What is the area of the smaller sector AOB?', '["18π", "16π", "36π", "9π"]'::jsonb, 0, null, 'Sector area = (80/360)π(81) = 18π.', 'published', 'import', now()),
('mathl3c_044', 'math', 3, 'Geometry and Trigonometry', 'Right triangles and trigonometry', null, null, 'In triangle PQR, angle Q = 90°, PQ = 9, and tan P = 4/3. What is the length of PR?', '["15", "13", "20", "12"]'::jsonb, 0, null, 'tan P = QR/PQ, so QR = 12. PR = √(81 + 144) = 15.', 'published', 'import', now()),
('mathl3c_045', 'math', 3, 'Geometry and Trigonometry', 'Right triangles and trigonometry', null, null, 'If sin θ = 0.6 and θ is acute, what is cos(90° − θ)?', '["1.6", "0.8", "0.6", "0.4"]'::jsonb, 2, null, 'cos(90° − θ) = sin θ = 0.6.', 'published', 'import', now()),
('mathl3c_046', 'math', 3, 'Geometry and Trigonometry', 'Right triangles and trigonometry', null, null, 'The diagonal of a square is 10√2. What is the area of the square?', null, null, '["100"]'::jsonb, 'The side is 10 (diagonal = side × √2), so the area is 100.', 'published', 'import', now()),
('mathl3c_047', 'math', 3, 'Geometry and Trigonometry', 'Lines, angles, and triangles', null, null, 'The interior angles of a regular polygon each measure 140°. How many sides does the polygon have?', '["7", "10", "8", "9"]'::jsonb, 3, null, 'Each exterior angle is 40°, and 360 ÷ 40 = 9.', 'published', 'import', now()),
('mathl3c_048', 'math', 3, 'Geometry and Trigonometry', 'Lines, angles, and triangles', null, null, 'In the xy-plane, a triangle has vertices (0, 0), (8, 0), and (8, 6). What is the length of its longest side?', '["14", "12", "10", "8"]'::jsonb, 2, null, 'The longest side is the hypotenuse from (0, 0) to (8, 6): √(64 + 36) = 10.', 'published', 'import', now()),
('mathl3c_049', 'math', 3, 'Geometry and Trigonometry', 'Area and volume', null, null, 'A cone and a cylinder have the same radius and the same height. The cylinder''s volume is 90π. What is the cone''s volume?', '["270π", "60π", "30π", "45π"]'::jsonb, 2, null, 'A cone''s volume is one-third of a cylinder''s with the same base and height: 90π ÷ 3 = 30π.', 'published', 'import', now()),
('mathl3c_050', 'math', 3, 'Geometry and Trigonometry', 'Area and volume', null, null, 'A rectangular prism has a square base. Its height is twice the side of the base, and its volume is 250. What is the side length of the base?', null, null, '["5"]'::jsonb, 's × s × 2s = 2s^{3} = 250, so s^{3} = 125 and s = 5.', 'published', 'import', now()),
('rwl3c_001', 'rw', 3, 'Craft and Structure', 'Words in Context', 'When the government banned the export of raw wool in the 1600s, some English merchants found ways to ____ the law, shipping wool hidden in barrels labeled as salt or flour.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["reinforce", "circumvent", "publicize", "anticipate"]'::jsonb, 1, null, 'Finding a way around a rule is what circumvent means.', 'published', 'import', now()),
('rwl3c_002', 'rw', 3, 'Craft and Structure', 'Words in Context', 'Because only a few fragments of the ancient instrument survive, any reconstruction of how it sounded is necessarily ____; scholars must fill large gaps with educated guesses.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["definitive", "speculative", "trivial", "routine"]'::jsonb, 1, null, 'A theory based on limited evidence and guesswork is speculative.', 'published', 'import', now()),
('rwl3c_003', 'rw', 3, 'Craft and Structure', 'Words in Context', 'Although she was the expedition''s leader, the botanist showed great ____ to the local guides, following their advice about which trails were safe and which plants were poisonous.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["indifference", "rivalry", "deference", "hostility"]'::jsonb, 2, null, 'Yielding respectfully to someone''s judgment is deference.', 'published', 'import', now()),
('rwl3c_004', 'rw', 3, 'Craft and Structure', 'Words in Context', 'Engineers warn that paving over wetlands may ____ flooding in coastal towns, since the wetlands currently absorb much of the water during storms.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["explain", "exacerbate", "alleviate", "measure"]'::jsonb, 1, null, 'Making a problem worse is what exacerbate means.', 'published', 'import', now()),
('rwl3c_005', 'rw', 3, 'Craft and Structure', 'Words in Context', 'Archaeologists found that the artisans had fashioned blades from obsidian, a volcanic glass that can be chipped into edges sharper than modern steel.', null, 'As used in the text, what does the word "fashioned" most nearly mean?', '["made", "imagined", "styled", "traded"]'::jsonb, 0, null, 'The artisans shaped tools from obsidian, so "fashioned" means made.', 'published', 'import', now()),
('rwl3c_006', 'rw', 3, 'Craft and Structure', 'Words in Context', 'The first flight simulators of the 1920s were ____: wooden cockpits mounted on pivots, with no screens or instruments, that tipped as the trainee moved the controls.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["permanent", "costly", "sophisticated", "rudimentary"]'::jsonb, 3, null, 'Very basic, early-stage tools are rudimentary.', 'published', 'import', now()),
('rwl3c_007', 'rw', 3, 'Craft and Structure', 'Words in Context', 'Microplastics have been detected in Arctic snow, deep-sea sediment, and human blood. Their ____ has made it difficult for researchers to find truly uncontaminated samples to use as comparisons.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["scarcity", "ubiquity", "fragility", "novelty"]'::jsonb, 1, null, 'Being found everywhere is ubiquity.', 'published', 'import', now()),
('rwl3c_008', 'rw', 3, 'Craft and Structure', 'Words in Context', 'No written rule required the fishing crews to stay out of each other''s waters, but a ____ agreement, understood by everyone and never spoken aloud, kept the peace for generations.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["tacit", "public", "hostile", "explicit"]'::jsonb, 0, null, 'Agreement that is understood but never stated is tacit.', 'published', 'import', now()),
('rwl3c_009', 'rw', 3, 'Craft and Structure', 'Text Structure and Purpose', 'Since the 1980s, ecologists have tracked the spread of mountain pine beetles across western North America. The beetles now survive at higher elevations and farther north than in any previous record. Researchers suspect that warmer winters, which no longer kill most of the beetle larvae, have allowed this expansion.', null, 'Which choice best describes the function of the third sentence in the overall structure of the text?', '["It contradicts the finding described in the second sentence", "It describes the method used to gather the data", "It introduces a second, unrelated study", "It offers a possible reason for the finding described in the second sentence"]'::jsonb, 3, null, 'The third sentence suggests why the beetles spread farther: warmer winters no longer kill the larvae.', 'published', 'import', now()),
('rwl3c_010', 'rw', 3, 'Craft and Structure', 'Text Structure and Purpose', 'In the 1940s, poet Gwendolyn Brooks often wrote in traditional forms such as the sonnet, which had long been associated with European writers. She used these strict forms to depict the daily lives of Black residents of Chicago''s South Side, insisting that their experiences deserved the same careful artistry as any subject in poetry.', null, 'Which choice best states the main purpose of the text?', '["To describe how a writer used a particular form to give voice to a community", "To criticize a poet for using an outdated style", "To explain how to write a sonnet", "To compare two poets'' careers"]'::jsonb, 0, null, 'The text explains how Brooks used the sonnet to portray Black life in Chicago.', 'published', 'import', now()),
('rwl3c_011', 'rw', 3, 'Craft and Structure', 'Text Structure and Purpose', 'For much of the twentieth century, Neanderthals were portrayed as brutish and incapable of symbolic thought. Discoveries over the past few decades, however, include shell beads, eagle-talon jewelry, and cave markings that appear to have been made by Neanderthals. Many researchers now argue that Neanderthals'' mental abilities were far closer to those of early modern humans than once believed.', null, 'Which choice best describes the overall structure of the text?', '["It defines a term and gives examples", "It compares two inventions and selects the better one", "It presents a widely held assumption, describes evidence against it, and offers a revised view", "It narrates events in chronological order"]'::jsonb, 2, null, 'The text gives the old view of Neanderthals, new evidence, and a revised conclusion.', 'published', 'import', now()),
('rwl3c_012', 'rw', 3, 'Craft and Structure', 'Text Structure and Purpose', 'At first glance, the desert at night seems lifeless. Yet as temperatures fall, kangaroo rats, scorpions, and kit foxes emerge from their burrows, and the sand fills with tracks by morning.', null, 'Which choice best describes the function of the phrase "at first glance" in the text?', '["It marks a change in time from past to present", "It introduces a scientific measurement", "It indicates that the author agrees with the first impression", "It suggests that an initial impression will be shown to be misleading"]'::jsonb, 3, null, '"At first glance" signals that the following impression will be corrected.', 'published', 'import', now()),
('rwl3c_013', 'rw', 3, 'Craft and Structure', 'Cross-Text Connections', 'Text 1
As ocean temperatures rise, some scientists recommend breeding heat-tolerant corals in laboratories and transplanting them onto damaged reefs. These corals could help reefs survive future heat waves.

Text 2
Corals bred for heat tolerance often come from a small number of parent colonies. Planting them widely could reduce a reef''s genetic diversity, leaving it more vulnerable to diseases and other threats that heat tolerance does not address.', null, 'Based on the texts, how would the author of Text 2 most likely respond to the recommendation in Text 1?', '["By arguing that coral reefs are not threatened", "By claiming that heat-tolerant corals do not exist", "By warning that the recommendation could harm the ecosystems it is meant to protect", "By agreeing that the recommendation should be adopted immediately"]'::jsonb, 2, null, 'Text 2 points out that bred corals may reduce genetic diversity, a risk to reefs.', 'published', 'import', now()),
('rwl3c_014', 'rw', 3, 'Craft and Structure', 'Cross-Text Connections', 'Text 1
A painting in an ancient Egyptian tomb shows workers pouring water in front of a sledge carrying a giant statue. Some researchers argue that the water was part of a religious ritual.

Text 2
Physicists have shown that wetting sand to the right dampness can cut the force needed to drag a heavy sledge across it roughly in half. The tomb painting, in this view, records a practical engineering technique.', null, 'Which choice best describes how the author of Text 2 would most likely view the evidence in Text 1?', '["As evidence that the pyramids were built recently", "As consistent with an alternative explanation the author favors", "As unrelated to the question of pyramid construction", "As proof that Text 1''s explanation is correct"]'::jsonb, 1, null, 'Text 2 accepts the water evidence but uses it to support a different explanation.', 'published', 'import', now()),
('rwl3c_015', 'rw', 3, 'Information and Ideas', 'Central Ideas and Details', 'Many trees are linked underground by networks of fungi that wrap around their roots. Studies in the 1990s suggested that carbon could travel through these networks from one tree to another, leading to popular descriptions of a cooperative "wood wide web." More recent reviews, however, argue that much of the evidence is limited and that the amount of resources actually transferred may be small.', null, 'Which choice best states the main idea of the text?', '["Some trees appear to share resources through underground fungal networks, though scientists disagree about how significant this sharing is", "Scientists have proven that older trees care for their offspring", "Trees in forests compete for sunlight and never share resources", "Fungi are harmful to the trees they grow near"]'::jsonb, 0, null, 'The text describes the fungal network idea and notes ongoing debate about its importance.', 'published', 'import', now()),
('rwl3c_016', 'rw', 3, 'Information and Ideas', 'Central Ideas and Details', 'NASA had begun using electronic computers to calculate spacecraft orbits by 1962, but many astronauts were wary of trusting the new machines. Before his flight as the first American to orbit Earth, John Glenn reportedly asked that mathematician Katherine Johnson check the computer''s numbers by hand. "If she says they''re good," he said, "then I''m ready to go."', null, 'According to the text, what made Katherine Johnson''s calculations essential to John Glenn''s 1962 flight?', '["Glenn wanted her to personally confirm the computer''s orbit calculations before he would fly", "She designed the spacecraft''s heat shield", "She operated the launch controls", "She trained Glenn to pilot the capsule"]'::jsonb, 0, null, 'The text states that Glenn asked for Johnson to check the computer''s results.', 'published', 'import', now()),
('rwl3c_017', 'rw', 3, 'Information and Ideas', 'Central Ideas and Details', 'The following text is adapted from a poem.

The city never sleeps, they say, and it is true:
its sirens sing at three a.m., its trains
shake the window glass, and still I love
the way it hums, a thousand lives at once,
all rushing, all refusing to be still.', null, 'Based on the text, what is the speaker''s attitude toward the city?', '["Frightened by its size", "Bitter about having to leave it", "Indifferent to its noise and crowds", "Admiring of its energy despite its harshness"]'::jsonb, 3, null, 'The speaker lists harsh details yet describes them with wonder and affection.', 'published', 'import', now()),
('rwl3c_018', 'rw', 3, 'Information and Ideas', 'Command of Evidence', 'Researchers concluded that sleep after learning helps people retain new vocabulary.', '{"h": ["Group", "Recall before delay (%)", "Recall after 8-hour delay (%)"], "r": [["Slept", "81", "74"], ["Stayed awake", "80", "52"]]}'::jsonb, 'Which choice most effectively uses data from the table to support the researchers'' conclusion?', '["Participants who slept 8 hours recalled 74 percent of the words, compared with 52 percent for those who stayed awake, while the two groups scored similarly before the delay", "Participants who slept 8 hours recalled 74 percent of the words", "Both groups learned the same list of words", "The study included 60 participants"]'::jsonb, 0, null, 'The conclusion is that sleep improved memory, so the evidence must compare the groups after the delay and show they started out similar.', 'published', 'import', now()),
('rwl3c_019', 'rw', 3, 'Information and Ideas', 'Command of Evidence', 'An economist hypothesizes that building light-rail stations increases the value of nearby homes.', null, 'Which finding, if true, would most directly support the economist''s hypothesis?', '["Some residents prefer to drive to work", "Home values rose across the entire country", "Neighborhoods that gained a new light-rail station saw home values rise faster than similar neighborhoods without a station", "Light-rail trains are quieter than buses"]'::jsonb, 2, null, 'The hypothesis links stations to rising home values, so a comparison with similar neighborhoods without stations is the most direct support.', 'published', 'import', now()),
('rwl3c_020', 'rw', 3, 'Information and Ideas', 'Command of Evidence', 'In a letter to a colleague, an eighteenth-century astronomer reveals remarkable determination in the face of hardship.', null, 'Which quotation from the letter most effectively illustrates the claim?', '["\"Please send my regards to your family.\"", "\"The observatory roof leaks when it rains.\"", "\"The weather here has been unusually cold.\"", "\"I have measured the stars every clear night this winter, though my fingers are often too cold to hold the pencil.\""]'::jsonb, 3, null, 'The claim is about determination despite hardship; only this quotation shows persistent work in difficult conditions.', 'published', 'import', now()),
('rwl3c_021', 'rw', 3, 'Information and Ideas', 'Command of Evidence', 'A student concluded that adding protected bike lanes was associated with a large increase in cycling across all regions studied.', '{"h": ["Region", "Bike share before (%)", "Bike share after (%)"], "r": [["A", "2", "6"], ["B", "3", "7"], ["C", "4", "8"]]}'::jsonb, 'Which choice best describes data from the table that support the student''s conclusion?', '["Region C had the most bicycle trips before the lanes were added", "Region A''s bicycle share rose to 6 percent", "The study measured trips in three regions", "In all three regions, the share of trips taken by bicycle at least doubled after protected bike lanes were added"]'::jsonb, 3, null, 'The conclusion is general, so the best evidence shows the increase across every region.', 'published', 'import', now()),
('rwl3c_022', 'rw', 3, 'Information and Ideas', 'Inferences', 'During a severe drought on one of the Galápagos Islands in 1977, most of the small, soft seeds disappeared, leaving mainly large, hard seeds. Biologists Peter and Rosemary Grant found that the finches that survived tended to have larger, deeper beaks, and the next generation''s average beak size was measurably larger. This suggests that ____', null, 'Which choice most logically completes the text?', '["the finches began eating insects instead of seeds", "the larger beaks may be an adaptation to the harder seeds that remained after the drought", "the drought caused all of the finches to leave the island", "beak size has no connection to diet"]'::jsonb, 1, null, 'After the drought, only hard seeds remained, and the next generation had bigger beaks, suggesting adaptation.', 'published', 'import', now()),
('rwl3c_023', 'rw', 3, 'Information and Ideas', 'Inferences', 'Two libraries, one in Paris and one in Dublin, each own a medieval parchment fragment. The handwriting and ink are identical, the torn edges fit together, and a sentence that breaks off at the bottom of the Paris fragment continues at the top of the Dublin one. Scholars therefore conclude that ____', null, 'Which choice most logically completes the text?', '["parchment was not used in the medieval period", "the fragments probably came from a single document that was torn apart", "the document was never finished", "the fragments were written by different authors in different centuries"]'::jsonb, 1, null, 'Matching handwriting, ink, tear lines, and text that continues across pieces point to one original document.', 'published', 'import', now()),
('rwl3c_024', 'rw', 3, 'Information and Ideas', 'Inferences', 'A new rice variety produced 20 percent more grain than standard rice in drought years. In years with normal rainfall, however, it produced 10 percent less. These results suggest that ____', null, 'Which choice most logically completes the text?', '["farmers should never plant this variety", "the variety grows well in all conditions", "rain has no effect on rice", "the drought-tolerant trait comes with a cost in wetter conditions"]'::jsonb, 3, null, 'The variety wins in drought but loses in normal rainfall, showing a tradeoff.', 'published', 'import', now()),
('rwl3c_025', 'rw', 3, 'Information and Ideas', 'Inferences', 'Saturn''s rings are made mostly of bright, clean water ice. Dust from space constantly falls on the rings and should gradually darken them. Measurements by the Cassini spacecraft suggest that the rings have collected surprisingly little dust. Some scientists therefore argue that ____', null, 'Which choice most logically completes the text?', '["Saturn''s rings contain no ice", "the rings were formed by a passing star", "the rings likely formed relatively recently in Saturn''s history", "the rings are older than Saturn itself"]'::jsonb, 2, null, 'Clean ice that should darken over time suggests the rings haven''t existed long.', 'published', 'import', now()),
('rwl3c_026', 'rw', 3, 'Standard English Conventions', 'Boundaries', 'Many plants have internal ____ open their flowers at about the same time each day even when kept in constant darkness.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["clocks; they", "clocks, and, they", "clocks, they", "clocks they"]'::jsonb, 0, null, 'Two complete sentences are joined with a semicolon here.', 'published', 'import', now()),
('rwl3c_027', 'rw', 3, 'Standard English Conventions', 'Boundaries', 'Traditional Hawaiian poi requires only two ____ cooked taro root and water.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["ingredients:", "ingredients,", "ingredients;", "ingredients"]'::jsonb, 0, null, 'A colon introduces a list after a complete sentence.', 'published', 'import', now()),
('rwl3c_028', 'rw', 3, 'Standard English Conventions', 'Boundaries', 'The exhibit features works by Japanese artist Katsushika ____ print The Great Wave off Kanagawa is among the most recognized images in the world.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["Hokusai whose", "Hokusai. Whose", "Hokusai; whose", "Hokusai, whose"]'::jsonb, 3, null, 'The "whose" clause adds nonessential information about Hokusai and is set off with a comma.', 'published', 'import', now()),
('rwl3c_029', 'rw', 3, 'Standard English Conventions', 'Boundaries', 'NASA''s rovers have explored several regions of Mars: Gusev Crater, a possible ancient lakebed; Meridiani Planum, a plain rich in minerals that form in ____ Jezero Crater, home to an ancient river delta.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["water and", "water: and", "water, and", "water; and"]'::jsonb, 3, null, 'The items in this list contain their own commas, so semicolons must separate the items.', 'published', 'import', now()),
('rwl3c_030', 'rw', 3, 'Standard English Conventions', 'Boundaries', 'In her influential 1961 book, urban activist Jane Jacobs ____ that busy sidewalks with many shops make neighborhoods safer by keeping "eyes on the street."', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["argued:", "argued", "argued;", "argued,"]'::jsonb, 1, null, 'No punctuation is needed between "argued" and the "that" clause that follows.', 'published', 'import', now()),
('rwl3c_031', 'rw', 3, 'Standard English Conventions', 'Boundaries', 'Galileo''s improved ____ which magnified objects about twenty times—allowed him to see the moons of Jupiter in 1610.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["telescope—", "telescope,", "telescope", "telescope;"]'::jsonb, 0, null, 'The phrase began with a dash, so it must close with a dash.', 'published', 'import', now()),
('rwl3c_032', 'rw', 3, 'Standard English Conventions', 'Form, Structure, and Sense', 'The discovery of feathered dinosaur fossils in China ____ that many dinosaurs were more closely related to birds than once thought.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["prove", "have proven", "proves", "are proving"]'::jsonb, 2, null, 'The subject is "the discovery" (singular), not "fossils."', 'published', 'import', now()),
('rwl3c_033', 'rw', 3, 'Standard English Conventions', 'Form, Structure, and Sense', 'After reviewing all forty proposals, the committee announced that ____ would fund three projects in the coming year.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["it", "they", "them", "those"]'::jsonb, 0, null, 'The pronoun refers to "the committee," a singular collective noun acting as a unit.', 'published', 'import', now()),
('rwl3c_034', 'rw', 3, 'Standard English Conventions', 'Form, Structure, and Sense', 'When oceanographer Marie Tharp retired in the 1980s, she ____ the ocean floor for more than three decades.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["will map", "had been mapping", "has mapped", "maps"]'::jsonb, 1, null, 'The mapping had been going on for decades before a past event (her retirement), so the past perfect progressive is used.', 'published', 'import', now()),
('rwl3c_035', 'rw', 3, 'Standard English Conventions', 'Form, Structure, and Sense', 'The grant allows students to test water samples, to collect data on local wildlife, and ____ their own experiments.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["designing", "designed", "to design", "design"]'::jsonb, 2, null, 'The sentence''s items are parallel infinitives: to test, to collect, and to design.', 'published', 'import', now()),
('rwl3c_036', 'rw', 3, 'Standard English Conventions', 'Form, Structure, and Sense', 'If the bridge ____ any longer, it would require additional support towers in the middle of the river.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["has been", "was", "were", "is"]'::jsonb, 2, null, 'In a hypothetical "if" clause, the subjunctive "were" is used.', 'published', 'import', now()),
('rwl3c_037', 'rw', 3, 'Standard English Conventions', 'Form, Structure, and Sense', 'Both the bassist and the drummer tuned ____ instruments before the concert began.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["his or her", "its", "it''s", "their"]'::jsonb, 3, null, '"Both the bassist and the drummer" is a plural subject, so "their" is correct.', 'published', 'import', now()),
('rwl3c_038', 'rw', 3, 'Expression of Ideas', 'Transitions', 'When the Federal Reserve raises interest rates, borrowing becomes more expensive and spending tends to slow. ____ when it lowers rates, loans become cheaper and spending often increases.', null, 'Which choice completes the text with the most logical transition?', '["Conversely,", "Likewise,", "Moreover,", "Consequently,"]'::jsonb, 0, null, 'The second sentence describes the opposite situation, so "Conversely" fits.', 'published', 'import', now()),
('rwl3c_039', 'rw', 3, 'Expression of Ideas', 'Transitions', 'The Svalbard Global Seed Vault stores backup samples of crops from nearly every country. ____ in 2015, researchers withdrew seeds from the vault to replace collections damaged by war in Syria, the first withdrawal in its history.', null, 'Which choice completes the text with the most logical transition?', '["Notably,", "Instead,", "Otherwise,", "Previously,"]'::jsonb, 0, null, 'The sentence highlights an especially significant detail, so "Notably" fits.', 'published', 'import', now()),
('rwl3c_040', 'rw', 3, 'Expression of Ideas', 'Transitions', 'In 1928, Alexander Fleming noticed that mold had killed bacteria in one of his lab dishes. ____ researchers Howard Florey and Ernst Chain developed a way to produce the mold''s active chemical, penicillin, in large amounts.', null, 'Which choice completes the text with the most logical transition?', '["For instance,", "Similarly,", "Subsequently,", "In contrast,"]'::jsonb, 2, null, 'The events follow in time order, so "Subsequently" fits.', 'published', 'import', now()),
('rwl3c_041', 'rw', 3, 'Expression of Ideas', 'Transitions', 'Electric cars produce no tailpipe emissions and are cheaper to fuel than gasoline cars. ____ manufacturing their batteries requires mining and energy. But over a car''s lifetime, studies find that electric cars typically produce fewer total emissions.', null, 'Which choice completes the text with the most logical transition?', '["For instance,", "Therefore,", "Similarly,", "Granted,"]'::jsonb, 3, null, 'The sentence concedes a drawback before the author''s main point, so "Granted" fits.', 'published', 'import', now()),
('rwl3c_042', 'rw', 3, 'Expression of Ideas', 'Transitions', 'The city aims to plant 100,000 new trees within a decade. ____ it has begun offering free saplings to residents and hiring crews to plant along major streets.', null, 'Which choice completes the text with the most logical transition?', '["For example,", "To that end,", "In contrast,", "Even so,"]'::jsonb, 1, null, 'The second sentence describes steps taken toward the goal in the first, so "To that end" fits.', 'published', 'import', now()),
('rwl3c_043', 'rw', 3, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• The Great Wall of China was built to protect against invasions.
• Construction took place over roughly 2,000 years.
• Including all of its branches, it is more than 13,000 miles long.
• Many workers helped build it.
• It attracts millions of tourists each year.', null, 'The student wants to emphasize the scale of the Great Wall of China. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["The Great Wall was built to protect against invasions.", "Including all of its branches, the Great Wall of China stretches more than 13,000 miles, built over roughly two thousand years.", "Many workers helped build the Great Wall.", "The Great Wall is a popular tourist destination."]'::jsonb, 1, null, 'Only this choice emphasizes the wall''s enormous length and the time it took to build.', 'published', 'import', now()),
('rwl3c_044', 'rw', 3, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• In 1977, scientists in the submersible Alvin discovered hydrothermal vents near the Galápagos Islands.
• Giant tube worms, clams, and crabs live around the vents.
• These communities get energy from chemicals released by the vents, not from sunlight.
• Before this, scientists believed all ecosystems depended on sunlight.', null, 'The student wants to explain how the discovery changed scientists'' understanding. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Giant tube worms live near the vents.", "Hydrothermal vents were discovered in 1977.", "The discovery of hydrothermal vent communities in 1977 showed that entire ecosystems could thrive without sunlight, powered instead by chemicals from Earth''s interior.", "The submersible Alvin explored the vents."]'::jsonb, 2, null, 'Only this choice explains how the discovery changed scientists'' thinking.', 'published', 'import', now()),
('rwl3c_045', 'rw', 3, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• Things Fall Apart is a novel by Nigerian author Chinua Achebe.
• It was published in 1958.
• It follows Okonkwo, an Igbo leader, as European colonizers arrive.
• It has sold more than 20 million copies.
• Its title comes from a poem by W. B. Yeats.', null, 'The student wants to introduce the novel and its author to an audience unfamiliar with them. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["The novel''s title comes from a poem by W. B. Yeats.", "Things Fall Apart has sold more than 20 million copies.", "Things Fall Apart, a 1958 novel by Nigerian writer Chinua Achebe, tells the story of an Igbo leader whose community is transformed by the arrival of European colonizers.", "Chinua Achebe was born in 1930."]'::jsonb, 2, null, 'An introduction should identify the work, its author, and its subject; only this choice does all three.', 'published', 'import', now()),
('rwl2d_001', 'rw', 2, 'Craft and Structure', 'Words in Context', 'Holi, the Hindu spring festival, is famous for its ____ colors: crowds toss clouds of bright pink, yellow, green, and blue powder into the air.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["dull", "faded", "plain", "vibrant"]'::jsonb, 3, null, 'Bright, lively colors are vibrant.', 'published', 'import', now()),
('rwl2d_002', 'rw', 2, 'Craft and Structure', 'Words in Context', 'The release of the new space telescope''s first images was eagerly ____; astronomers had waited more than two decades to see what it would reveal.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["ignored", "forgotten", "anticipated", "regretted"]'::jsonb, 2, null, 'Something people look forward to and expect is anticipated.', 'published', 'import', now()),
('rwl2d_003', 'rw', 2, 'Craft and Structure', 'Words in Context', 'High on the Tibetan Plateau, vegetation is ____: only scattered grasses and low shrubs survive the thin air, strong winds, and short growing season.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["crowded", "lush", "dense", "sparse"]'::jsonb, 3, null, 'Thinly scattered plants are sparse.', 'published', 'import', now()),
('rwl2d_004', 'rw', 2, 'Craft and Structure', 'Words in Context', 'Scientists at about twenty institutions in six countries ____ on the Human Genome Project, sharing data openly so that the human genetic code could be mapped.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["withdraw", "argue", "collaborate", "compete"]'::jsonb, 2, null, 'Working together is what collaborate means.', 'published', 'import', now()),
('rwl2d_005', 'rw', 2, 'Craft and Structure', 'Words in Context', 'Although the singer hit every note correctly, the critic found the performance flat, saying it lacked the passion that had made her earlier concerts so moving.', null, 'As used in the text, what does the word "flat" most nearly mean?', '["fixed in price", "deflated", "lacking energy", "level"]'::jsonb, 2, null, 'The critic says the performance had no energy, so "flat" means lacking energy.', 'published', 'import', now()),
('rwl2d_006', 'rw', 2, 'Craft and Structure', 'Words in Context', 'After testing the paper, ink, and handwriting, experts confirmed that the letter was ____: it had truly been written by Abigail Adams in 1776.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["damaged", "modern", "fake", "authentic"]'::jsonb, 3, null, 'Experts confirmed the letter was genuine, which is what authentic means.', 'published', 'import', now()),
('rwl2d_007', 'rw', 2, 'Craft and Structure', 'Words in Context', 'Thick fog can ____ rescue efforts at sea, making it difficult for helicopter crews to spot boats in distress.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["describe", "hinder", "help", "measure"]'::jsonb, 1, null, 'Something that makes a task harder hinders it.', 'published', 'import', now()),
('rwl2d_008', 'rw', 2, 'Craft and Structure', 'Words in Context', 'Agatha Christie was remarkably ____, writing 66 detective novels, 14 short story collections, and the world''s longest-running play, The Mousetrap.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["reluctant", "prolific", "anonymous", "unproductive"]'::jsonb, 1, null, 'Someone who produces a great many works is prolific.', 'published', 'import', now()),
('rwl2d_009', 'rw', 2, 'Craft and Structure', 'Text Structure and Purpose', 'In many rural areas, people walk long distances to collect water and carry heavy containers home on their heads. The Q Drum, a doughnut-shaped plastic container, can be filled with 50 liters of water and rolled along the ground with a rope. Even a child can pull it, freeing families from one of their most exhausting daily tasks.', null, 'Which choice best states the main purpose of the text?', '["To explain how a simple invention improved life for many people", "To describe the history of rubber", "To argue that bicycles are better than cars", "To compare two inventors"]'::jsonb, 0, null, 'The text describes how the Q Drum helps people transport water more easily.', 'published', 'import', now()),
('rwl2d_010', 'rw', 2, 'Craft and Structure', 'Text Structure and Purpose', 'Many inventions have been inspired by nature. After noticing how burrs stuck to his dog''s fur, Swiss engineer George de Mestral studied them under a microscope and developed Velcro. The practice of copying nature''s designs is now known as biomimicry.', null, 'Which choice best describes the function of the second sentence in the overall structure of the text?', '["It gives an example that illustrates the claim in the first sentence", "It states the conclusion of the text", "It introduces a new topic", "It contradicts the claim in the first sentence"]'::jsonb, 0, null, 'The second sentence gives the example of Velcro inspired by burrs.', 'published', 'import', now()),
('rwl2d_011', 'rw', 2, 'Craft and Structure', 'Text Structure and Purpose', 'In 1906, a powerful earthquake struck San Francisco, and the fires that followed destroyed much of the city. In the decades afterward, engineers studied which buildings had survived and why. Their findings helped shape later building codes designed to help structures withstand earthquakes.', null, 'Which choice best describes the overall structure of the text?', '["It argues for and against a proposal", "It describes a historical event and then explains its long-term effect", "It compares two cities and chooses one", "It lists several unrelated facts"]'::jsonb, 1, null, 'The text describes the 1906 earthquake and then how lessons from it influenced later building codes.', 'published', 'import', now()),
('rwl2d_012', 'rw', 2, 'Craft and Structure', 'Text Structure and Purpose', 'Some mammals have surprising traits. The platypus, for instance, lays eggs and can sense the electric signals given off by the muscles of its prey.', null, 'Which choice best describes the function of the phrase "for instance" in the text?', '["It introduces a conclusion", "It introduces a specific example of the general point", "It signals a contrast", "It shows a change in time"]'::jsonb, 1, null, '"For instance" introduces the example of the platypus.', 'published', 'import', now()),
('rwl2d_013', 'rw', 2, 'Craft and Structure', 'Cross-Text Connections', 'Text 1
To improve air quality, cities should plant trees along every major street. Trees absorb pollutants and provide shade.

Text 2
Trees help, but in dense downtowns there is often no space for them. Green walls, vertical gardens attached to buildings, can filter air in places where street trees cannot grow.', null, 'Based on the texts, how would the author of Text 2 most likely respond to Text 1?', '["By arguing that pollution is not a problem", "By agreeing completely with Text 1''s plan", "By claiming that cities do not need trees", "By agreeing that the goal is worthwhile but arguing that it can be met in a different way"]'::jsonb, 3, null, 'Text 2 shares the goal of cleaner air but proposes green walls on buildings instead of street trees.', 'published', 'import', now()),
('rwl2d_014', 'rw', 2, 'Craft and Structure', 'Cross-Text Connections', 'Text 1
Dogs seem able to tell when their owners are happy or upset. Some researchers suspect that dogs can read human facial expressions.

Text 2
In a study, dogs were shown photographs of human faces. They looked longer at angry faces than at happy ones and showed signs of stress, suggesting they recognized the difference.', null, 'Which choice best describes how the two texts are related?', '["Both texts describe different animals", "Text 2 shows that the hypothesis in Text 1 is false", "Text 2 provides evidence that supports the hypothesis in Text 1", "Text 1 summarizes the study described in Text 2"]'::jsonb, 2, null, 'Text 1 suggests that dogs read faces; Text 2''s study supports this.', 'published', 'import', now()),
('rwl2d_015', 'rw', 2, 'Information and Ideas', 'Central Ideas and Details', 'Smoke from large wildfires can travel thousands of miles. In 2023, smoke from fires in Canada drifted over New York City, turning the sky orange and pushing air quality to some of the worst levels ever recorded there. Doctors reported increases in asthma attacks and other breathing problems far from any flames.', null, 'Which choice best states the main idea of the text?', '["Wildfire smoke can harm health far from the fires that produce it", "Smoke stays near the fires that create it", "Most wildfires are started by lightning", "Wildfires are becoming less common"]'::jsonb, 0, null, 'The text explains that smoke travels long distances and causes health problems there.', 'published', 'import', now()),
('rwl2d_016', 'rw', 2, 'Information and Ideas', 'Central Ideas and Details', 'In 1885, Vermont farmer Wilson Bentley became the first person to photograph a single snowflake. Over the next 46 years, he captured more than 5,000 images, attaching a camera to a microscope. His photographs revealed that every snowflake had its own intricate pattern, and he concluded that no two were exactly alike.', null, 'According to the text, why did Wilson Bentley photograph snowflakes?', '["To measure how much snow fell each year", "To prove that snow is made of dust", "To show that each snowflake has its own unique pattern", "To sell pictures of winter scenes"]'::jsonb, 2, null, 'The text says his photographs revealed that no two snowflakes looked alike.', 'published', 'import', now()),
('rwl2d_017', 'rw', 2, 'Information and Ideas', 'Central Ideas and Details', 'Many people think of bats only as insect eaters, but some species feed on nectar. In Mexico, the lesser long-nosed bat pollinates the flowers of the agave plant. Farmers who allow some agave plants to flower help the bats survive, and the bats in turn keep the agave plants genetically healthy.', null, 'Which choice best states the main idea of the text?', '["Most bats eat only insects", "Pollinators like bats play an important role in producing some foods", "Bats are dangerous to farmers", "Agave plants grow only in deserts"]'::jsonb, 1, null, 'The text explains that bats pollinate agave, which is needed for certain products.', 'published', 'import', now()),
('rwl2d_018', 'rw', 2, 'Information and Ideas', 'Central Ideas and Details', 'The following text is adapted from a short story.

The radio on Grandpa''s shelf hadn''t worked in thirty years. When Tomás asked why he didn''t throw it out, Grandpa ran his thumb along its wooden case. "My father and I listened to every Dodgers game on this," he said. "Sometimes I can still hear the announcer when I look at it."', null, 'Based on the text, why does Grandpa keep the old radio?', '["He plans to sell it", "It reminds him of listening to baseball games with his father", "It still works better than new radios", "He doesn''t know how to use a phone"]'::jsonb, 1, null, 'He explains that the radio brings back memories of his father.', 'published', 'import', now()),
('rwl2d_019', 'rw', 2, 'Information and Ideas', 'Command of Evidence', 'A student claims that students who eat breakfast tend to do better on morning math tests.', '{"h": ["Group", "Avg. test score"], "r": [["Ate breakfast", "84"], ["Skipped breakfast", "76"]]}'::jsonb, 'Which choice most effectively uses data from the table to support the student''s claim?', '["Students who ate breakfast averaged 84 on the math test, compared with 76 for students who skipped breakfast", "Some students skipped breakfast", "Students who ate breakfast averaged 84", "The test had 40 questions"]'::jsonb, 0, null, 'The claim compares breakfast eaters and skippers, so both averages are needed.', 'published', 'import', now()),
('rwl2d_020', 'rw', 2, 'Information and Ideas', 'Command of Evidence', 'A researcher claims that hanging posters about reading in classrooms caused students to spend more time reading.', null, 'Which finding, if true, would most directly weaken the researcher''s claim?', '["Students enjoyed looking at the posters", "The posters featured popular book characters", "The posters were placed near the library", "Similar classrooms with no posters had the same increase in reading time"]'::jsonb, 3, null, 'If classrooms without posters improved equally, the posters didn''t cause the change.', 'published', 'import', now()),
('rwl2d_021', 'rw', 2, 'Information and Ideas', 'Command of Evidence', 'In a short story, Rosa is described as determined.', null, 'Which quotation from the story best supports the idea that Rosa is determined?', '["\"Rosa fell off the skateboard a dozen times that afternoon, and a dozen times she climbed back on.\"", "\"The skate park was crowded on weekends.\"", "\"Rosa''s friends went home for dinner.\"", "\"Rosa''s skateboard was painted bright orange.\""]'::jsonb, 0, null, 'Getting back on after every fall shows determination.', 'published', 'import', now()),
('rwl2d_022', 'rw', 2, 'Information and Ideas', 'Command of Evidence', 'The table shows electric car sales in a state. It shows that ____.', '{"h": ["Year", "Electric cars sold"], "r": [["2020", "12,000"], ["2021", "19,000"], ["2022", "31,000"], ["2023", "44,000"]]}'::jsonb, 'Which choice best uses data from the table to complete the statement?', '["electric car sales stayed the same each year", "electric car sales fell after 2021", "the number of electric cars sold in the state increased every year shown", "fewer electric cars were sold in 2023 than in 2020"]'::jsonb, 2, null, 'Sales rose from 12,000 to 19,000 to 31,000 to 44,000.', 'published', 'import', now()),
('rwl2d_023', 'rw', 2, 'Information and Ideas', 'Inferences', 'Before building a suspension bridge across a windy strait, engineers tested a scale model in a wind tunnel. They then gave the bridge deck a sleek, wing-like shape that lets air flow smoothly around it. These details suggest that ____', null, 'Which choice most logically completes the text?', '["the bridge was built of wood", "the bridge was probably designed to withstand strong winds", "the engineers did not consider weather", "the bridge is closed whenever it is windy"]'::jsonb, 1, null, 'Wind-tunnel testing and an aerodynamic deck suggest the bridge was designed for strong winds.', 'published', 'import', now()),
('rwl2d_024', 'rw', 2, 'Information and Ideas', 'Inferences', 'A beekeeper noticed that honey from her spring harvest was light and mild, while honey from late summer was dark and strong-tasting. When she examined pollen grains in each batch, she found mostly clover pollen in the spring honey and mostly buckwheat pollen in the summer honey. This suggests that the difference in taste exists because ____', null, 'Which choice most logically completes the text?', '["the jars were mislabeled", "all honey tastes the same", "the honey may have been gathered from different types of flowers", "the bees were sick"]'::jsonb, 2, null, 'Different pollen in each jar suggests the bees visited different flowers.', 'published', 'import', now()),
('rwl2d_025', 'rw', 2, 'Information and Ideas', 'Inferences', 'A wooden boat dock built in 1970 once extended over the deep water of a desert lake. Today, the end of the dock sits on dry, cracked mud more than 200 feet from the water''s edge. This suggests that ____', null, 'Which choice most logically completes the text?', '["the dock was built too long", "the lake''s water level has dropped over the years", "the lake has gotten deeper", "boats are no longer allowed on the lake"]'::jsonb, 1, null, 'The dock now sits far from the water, suggesting the water has receded.', 'published', 'import', now()),
('rwl2d_026', 'rw', 2, 'Information and Ideas', 'Inferences', 'Two groups of students with similar grades took the same reading test in the fall and spring. One group attended an after-school tutoring program; the other did not. The tutored group''s scores rose by 15 points, while the other group''s scores rose by 3 points. This suggests that ____', null, 'Which choice most logically completes the text?', '["the test was easier for everyone", "the students in the program studied less", "the tutoring program may have helped the students improve", "the tutoring program lowered scores"]'::jsonb, 2, null, 'Only the tutored group improved much, suggesting the program helped.', 'published', 'import', now()),
('rwl2d_027', 'rw', 2, 'Standard English Conventions', 'Boundaries', 'During a total solar ____ moon completely blocks the sun, and the sky grows dark for a few minutes.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["eclipse. The,", "eclipse the", "eclipse; the", "eclipse, the"]'::jsonb, 3, null, 'A comma follows the introductory phrase "During a total solar eclipse."', 'published', 'import', now()),
('rwl2d_028', 'rw', 2, 'Standard English Conventions', 'Boundaries', 'A traditional mariachi band includes several string ____ violin, the guitar, and the guitarrón.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["instruments; the", "instruments: the", "instruments, the:", "instruments the"]'::jsonb, 1, null, 'A colon introduces the list after a complete sentence.', 'published', 'import', now()),
('rwl2d_029', 'rw', 2, 'Standard English Conventions', 'Boundaries', 'George Washington ____ agricultural scientist, developed hundreds of uses for peanuts and sweet potatoes.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["Carver; an", "Carver an", "Carver. An", "Carver, an"]'::jsonb, 3, null, 'The phrase "an agricultural scientist…" renames Carver and is set off by commas.', 'published', 'import', now()),
('rwl2d_030', 'rw', 2, 'Standard English Conventions', 'Boundaries', 'Some mountains in Africa are always capped with ____ are covered in tropical forest.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["snow others", "snow, others", "snow: others,", "snow; others"]'::jsonb, 3, null, 'Two complete sentences are joined with a semicolon.', 'published', 'import', now()),
('rwl2d_031', 'rw', 2, 'Standard English Conventions', 'Boundaries', 'The ____ that hit the coast last week knocked out power to thousands of homes.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["storm", "storm:", "storm;", "storm,"]'::jsonb, 0, null, 'No punctuation belongs between the subject "the storm" and its verb.', 'published', 'import', now()),
('rwl2d_032', 'rw', 2, 'Standard English Conventions', 'Boundaries', 'The Colosseum—the largest amphitheater ever built in ancient ____ could hold about 50,000 spectators.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["Rome—", "Rome,", "Rome", "Rome;"]'::jsonb, 0, null, 'The phrase began with a dash, so it must end with a dash.', 'published', 'import', now()),
('rwl2d_033', 'rw', 2, 'Standard English Conventions', 'Form, Structure, and Sense', 'The list of endangered species in the region ____ updated every five years.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["is", "are", "have been", "were"]'::jsonb, 0, null, 'The subject "the list" is singular.', 'published', 'import', now()),
('rwl2d_034', 'rw', 2, 'Standard English Conventions', 'Form, Structure, and Sense', 'The twins trained together for years, and in 2020 ____ both qualified for the national swim team.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["she", "they", "he", "it"]'::jsonb, 1, null, 'The pronoun refers to "the twins," which is plural.', 'published', 'import', now()),
('rwl2d_035', 'rw', 2, 'Standard English Conventions', 'Form, Structure, and Sense', 'Since 2010, the number of community gardens in the city ____ from 12 to more than 80.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["will grow", "has grown", "had grown", "grew"]'::jsonb, 1, null, '"Since 2010" describes an action continuing to the present, so the present perfect is used.', 'published', 'import', now()),
('rwl2d_036', 'rw', 2, 'Standard English Conventions', 'Form, Structure, and Sense', 'At the summer art camp, students spend their mornings sketching, sculpting, and ____.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["paint", "to painting", "painting", "painted"]'::jsonb, 2, null, 'The list is parallel: sketching, sculpting, and painting.', 'published', 'import', now()),
('rwl2d_037', 'rw', 2, 'Standard English Conventions', 'Form, Structure, and Sense', 'After practicing every day, Kenji made ____ mistakes during his piano recital.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["less", "littler", "lesser", "fewer"]'::jsonb, 3, null, '"Fewer" is used with countable nouns such as "mistakes."', 'published', 'import', now()),
('rwl2d_038', 'rw', 2, 'Standard English Conventions', 'Form, Structure, and Sense', 'The octopus can change the color and texture of ____ skin in less than a second.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["their", "it''s", "its", "his"]'::jsonb, 2, null, 'The possessive pronoun refers to "the octopus," so "its" is correct.', 'published', 'import', now()),
('rwl2d_039', 'rw', 2, 'Expression of Ideas', 'Transitions', 'More than two feet of snow fell overnight in the mountain town. ____ every school and most roads were closed the next morning.', null, 'Which choice completes the text with the most logical transition?', '["Consequently,", "However,", "For example,", "Similarly,"]'::jsonb, 0, null, 'The roads closing was caused by the snow, so a result transition fits.', 'published', 'import', now()),
('rwl2d_040', 'rw', 2, 'Expression of Ideas', 'Transitions', 'The Appalachian Mountains are among the oldest on Earth, formed more than 400 million years ago. ____ the Himalayas are relatively young and are still rising today.', null, 'Which choice completes the text with the most logical transition?', '["Likewise,", "Therefore,", "For instance,", "In contrast,"]'::jsonb, 3, null, 'The second sentence describes the opposite (ancient vs. young), so "In contrast" fits.', 'published', 'import', now()),
('rwl2d_041', 'rw', 2, 'Expression of Ideas', 'Transitions', 'To make a simple compass, first rub a sewing needle against a magnet about fifty times in the same direction. ____ push the needle through a small piece of cork and float it in a bowl of water.', null, 'Which choice completes the text with the most logical transition?', '["Next,", "In contrast,", "However,", "For example,"]'::jsonb, 0, null, 'The steps follow in order, so "Next" fits.', 'published', 'import', now()),
('rwl2d_042', 'rw', 2, 'Expression of Ideas', 'Transitions', 'Learning a second language can open doors to new careers. ____ studies suggest that it may help keep the brain sharp later in life.', null, 'Which choice completes the text with the most logical transition?', '["Otherwise,", "Instead,", "However,", "Moreover,"]'::jsonb, 3, null, 'The second sentence adds another benefit, so "Moreover" fits.', 'published', 'import', now()),
('rwl2d_043', 'rw', 2, 'Expression of Ideas', 'Transitions', 'The Titanic was built with sixteen watertight compartments, and many people believed it could not sink. ____ it sank on its first voyage in 1912 after striking an iceberg.', null, 'Which choice completes the text with the most logical transition?', '["For instance,", "Even so,", "As a result,", "Likewise,"]'::jsonb, 1, null, 'The ship was thought unsinkable, yet it sank, so a concession transition fits.', 'published', 'import', now()),
('rwl2d_044', 'rw', 2, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• The Amazon rainforest covers parts of nine countries.
• Its trees release about 20 billion tons of water vapor each day.
• That is more water than the Amazon River carries into the ocean daily.
• It is home to millions of animal species.
• Some areas have been cleared for farming.', null, 'The student wants to emphasize how much water the Amazon rainforest releases. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Many animal species live in the Amazon.", "The Amazon rainforest covers parts of nine countries.", "The Amazon''s trees release about 20 billion tons of water vapor into the air each day, more than the Amazon River carries into the ocean.", "Some of the Amazon has been cleared for farming."]'::jsonb, 2, null, 'Only this choice focuses on the huge amount of water released.', 'published', 'import', now()),
('rwl2d_045', 'rw', 2, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• The Rosetta Stone was found in Egypt in 1799.
• It repeats the same decree in three scripts: hieroglyphs, Demotic, and ancient Greek.
• Scholars could already read ancient Greek.
• Jean-François Champollion used it to decode hieroglyphs in 1822.
• It is displayed in the British Museum.', null, 'The student wants to explain the purpose of the Rosetta Stone''s three scripts. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Because the Rosetta Stone repeats the same message in hieroglyphs, Demotic, and Greek, scholars could use the Greek text to decode the hieroglyphs.", "The Rosetta Stone is in the British Museum.", "The Rosetta Stone is made of granodiorite.", "The Rosetta Stone was found in 1799."]'::jsonb, 0, null, 'Only this choice explains why having the three scripts mattered.', 'published', 'import', now()),
('rwl2d_046', 'rw', 2, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• Clouds are made of water droplets or ice crystals.
• Cirrus clouds are thin and wispy.
• They form high in the sky and are made of ice crystals.
• Cumulus clouds are puffy.
• They form at lower altitudes and can grow into storm clouds.', null, 'The student wants to contrast the two kinds of clouds. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["While cirrus clouds are thin and wispy and form high in the sky, cumulus clouds are puffy and form much lower.", "Clouds are made of water droplets or ice crystals.", "Cumulus clouds can grow into storm clouds.", "Cirrus clouds are made of ice crystals."]'::jsonb, 0, null, 'Only this choice states differences between the two kinds of clouds.', 'published', 'import', now())
on conflict (id) do nothing;
